last_record.sparql_query:
SELECT DISTINCT ?item ?itemLabelEn ?itemLabelRu WHERE {
      ?item wdt:P31/wdt:P279* wd:Q746549 .
      wd:Q177 (wdt:P527|wdt:P186) ?bridgeIngredient .
      ?item (wdt:P527|wdt:P186) ?bridgeIngredient .
      ?item wdt:P31/wdt:P279* wd:Q28803 .
      FILTER(?item != wd:Q177)
      ?item rdfs:label ?itemLabelEn FILTER(LANG(?itemLabelEn) = "en") .
      OPTIONAL { ?item rdfs:label ?itemLabelRu FILTER(LANG(?itemLabelRu) = "ru") . }
    }
    LIMIT 701
